@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));
/* Margin notes are for readers with a cursor; a touch device has no room for
   them and no pointer to aim. */
@custom-variant pointer-fine (@media (pointer: fine));

/* ---------------------------------------------------------------------------
   Tokens. A neutral zinc system — no chromatic accent. Colour appears only
   where it carries meaning (links, status). `--line` is the hairline the
   whole frame is drawn with: the border colour, softened toward the
   background so a full-bleed rule reads as structure rather than a box.
--------------------------------------------------------------------------- */

:root {
  color-scheme: light;

  /* Near-white, not paper-white. Pure white leaves `--card`, `--popover` and
     the hairlines nowhere to go: a raised panel and the page it sits on were
     the same value, so the frame read as flat. Backing the sheet off to
     zinc-50 gives the white surfaces above it somewhere to be raised to, and
     mirrors dark, where `--card` sits above `--background` rather than on it.
     `lib/theme.ts` carries the same number for the three consumers that
     cannot read a custom property. */
  --background: oklch(0.985 0 0); /* zinc-50 */
  --foreground: oklch(0.141 0.005 285.823); /* zinc-950 */

  --primary: oklch(0.141 0.005 285.823);
  --primary-foreground: oklch(0.985 0 0);

  --secondary: oklch(0.967 0.001 286.375); /* zinc-100 */
  --secondary-foreground: oklch(0.141 0.005 285.823);

  --muted: oklch(0.967 0.001 286.375); /* zinc-100 — a surface */
  --muted-foreground: oklch(0.552 0.016 285.938); /* zinc-500 */

  --card: oklch(1 0 0);
  --card-foreground: oklch(0.141 0.005 285.823);

  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.141 0.005 285.823);

  --accent: oklch(0.967 0.001 286.375); /* zinc-100 */
  --accent-muted: color-mix(in oklab, var(--accent) 50%, transparent);
  --accent-foreground: oklch(0.21 0.006 285.885);

  --border: oklch(0.92 0.004 286.32); /* zinc-200 */
  --line: color-mix(in oklab, var(--border) 64%, var(--background));
  --input: oklch(0.92 0.004 286.32);
  --ring: oklch(0.705 0.015 286.067); /* zinc-400 */

  --info: oklch(0.67 0.17 244.98);
  --success: oklch(0.723 0.219 149.579);
  --destructive: oklch(0.577 0.245 27.325);
  --link: oklch(0.488 0.243 264.376); /* blue-700 */

  --surface: oklch(0.967 0.001 286.375); /* zinc-100 — recessed from the sheet */
  --surface-foreground: oklch(0.141 0.005 285.823);

  --code: var(--background);
  --code-foreground: var(--foreground);
  --code-number: oklch(0.24 0.01 0 / 0.3);
  --code-highlight: oklch(0.49 0.18 257.61 / 0.06);

  --selection: oklch(0.141 0.005 285.823);
  --selection-foreground: oklch(0.985 0 0);

  --header-height: --spacing(14);

  /* How far a floating control has to sit above the last pixel of the page to
     stay off the footer signature. The signature runs the full width of the
     viewport, so its height is a fixed fraction of that width — the kept part
     of the wordmark box, 168 * 0.75 / 1400 — and one rem of air on top. Both
     the dock and the way back up read this, so nothing ever lands on the name
     at any viewport. `lib/wordmark-dots.ts` holds the numbers it derives from. */
  --signature-clear: calc(9vw + --spacing(4));

  /* How much of the signature's baked weight survives this theme. The same
     dots at the same alpha do not weigh the same in both: lightness is steep
     near black and flat near white, so a sparse field lifting off a dark page
     shifts it several times as far as the same field darkening a light one.

     It is a multiplier, not a weight — the weight itself stays in the preset
     the studio baked, so retuning ink there still moves the real mark. Light
     is the reference at 1. Dark carries the correction; `tools/dither.js`
     holds the same factor so the studio's dark preview does not lie about
     what ships, and a test in `lib/wordmark-dots.test.ts` keeps the two
     honest. */
  --wordmark-ink: 1;
}

.dark {
  color-scheme: dark;

  --background: oklch(0.141 0.005 285.823);
  --foreground: oklch(0.985 0 0);

  --primary: oklch(0.985 0 0);
  --primary-foreground: oklch(0.141 0.005 285.823);

  --secondary: oklch(0.274 0.006 286.033); /* zinc-800 */
  --secondary-foreground: oklch(0.985 0 0);

  --muted: oklch(0.274 0.006 286.033);
  --muted-foreground: oklch(0.705 0.015 286.067); /* zinc-400 */

  --card: oklch(0.21 0.006 285.885); /* zinc-900 */
  --card-foreground: oklch(0.985 0 0);

  --popover: oklch(0.21 0.006 285.885);
  --popover-foreground: oklch(0.985 0 0);

  --accent: oklch(0.274 0.006 286.033);
  --accent-muted: color-mix(in oklab, var(--accent) 20%, transparent);
  --accent-foreground: oklch(0.985 0 0);

  --border: oklch(0.274 0.006 286.033);
  --input: lab(100% 0 0 / 0.15);
  --ring: oklch(0.552 0.016 285.938);

  --success: oklch(0.723 0.219 149.579);
  --destructive: oklch(0.505 0.213 27.518);
  --link: oklch(0.623 0.214 259.815); /* blue-500 */

  --surface: oklch(0.21 0.006 285.885);
  --surface-foreground: oklch(0.985 0 0);

  --code-number: oklch(0.43 0 0);
  --code-highlight: oklch(0.71 0.24 42.36 / 0.06);

  --selection: oklch(0.985 0 0);
  --selection-foreground: oklch(0.141 0.005 285.823);

  --wordmark-ink: 0.444;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);

  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);

  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);

  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);

  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);

  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);

  --color-accent: var(--accent);
  --color-accent-muted: var(--accent-muted);
  --color-accent-foreground: var(--accent-foreground);

  --color-border: var(--border);
  --color-line: var(--line);
  --color-input: var(--input);
  --color-ring: var(--ring);

  --color-info: var(--info);
  --color-success: var(--success);
  --color-destructive: var(--destructive);
  --color-link: var(--link);

  --color-surface: var(--surface);
  --color-surface-foreground: var(--surface-foreground);

  --color-code: var(--code);
  --color-code-foreground: var(--code-foreground);
  --color-code-number: var(--code-number);
  --color-code-highlight: var(--code-highlight);

  --color-selection: var(--selection);
  --color-selection-foreground: var(--selection-foreground);

  --font-sans: var(--font-geist-sans), ui-sans-serif, system-ui, sans-serif;
  --font-mono: var(--font-geist-mono), ui-monospace, SFMono-Regular, monospace;
  --font-heading: var(--font-sans);
  --font-serif: var(--font-plex-serif), ui-serif, Georgia, serif;
  --font-handwriting: var(--font-caveat), var(--font-sans);

  --default-mono-font-feature-settings: "ss11" 1, "zero" 1, "tnum" 1;

  --ease-out-quint: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-io: cubic-bezier(0.65, 0, 0.35, 1);
}

/* ---------------------------------------------------------------------------
   Utilities. The frame system: hairlines that span the viewport rather than
   stopping at the content rail, and diagonal hatching for the gaps between
   panels.
--------------------------------------------------------------------------- */

@utility link {
  @apply decoration-1 underline-offset-3 hover:underline;
}

@utility link-underline {
  @apply underline decoration-current/30 decoration-1 underline-offset-3 transition-colors hover:decoration-current;
}

@utility screen-line-top {
  @apply relative;

  &:before {
    content: "";
    @apply absolute top-0 left-[-100vw] -z-1 h-px w-[200vw] bg-line;
  }
}

@utility screen-line-bottom {
  @apply relative;

  &:after {
    content: "";
    @apply absolute bottom-0 left-[-100vw] -z-1 h-px w-[200vw] bg-line;
  }
}

@utility screen-dashed-line-top {
  @apply screen-line-top;

  &:before {
    content: "";
    @apply bg-inherit bg-[linear-gradient(to_right,var(--line)_4px,transparent_2px)] bg-size-[6px_1px] bg-repeat-x;
  }
}

@utility screen-dashed-line-bottom {
  @apply screen-line-bottom;

  &:after {
    content: "";
    @apply bg-inherit bg-[linear-gradient(to_right,var(--line)_4px,transparent_2px)] bg-size-[6px_1px] bg-repeat-x;
  }
}

@utility screen-line-top-none {
  @apply before:content-none;
}

@utility screen-line-bottom-none {
  @apply after:content-none;
}

@utility diagonal-stripes {
  @apply [--pattern-foreground:var(--color-line)]/56;
  @apply bg-[repeating-linear-gradient(315deg,var(--pattern-foreground)_0,var(--pattern-foreground)_1px,transparent_0,transparent_50%)] bg-size-[10px_10px];
}

@utility stripe-divider {
  @apply relative h-8;

  &:before {
    content: "";
    @apply absolute left-[-100vw] -z-1 h-full w-[200vw] diagonal-stripes;
  }
}

/* Pointer-coarse devices get a 24px-minimum hit area without a 24px box. */
@utility extend-touch-target {
  @media (pointer: coarse) {
    @apply relative touch-manipulation after:absolute after:-inset-2;
  }
}

/* The quiet control: a toolbar button that is an icon at rest and a surface
   only once it is under the pointer. Used by every action on a post — copy,
   share, the two arrows — so the row reads as one set rather than four
   buttons that happen to sit together. */
@utility action-button {
  @apply inline-flex h-8 min-w-8 items-center justify-center gap-1.5 rounded-lg px-2 text-sm text-muted-foreground transition-colors select-none active:scale-[0.98] hover:bg-accent hover:text-foreground disabled:pointer-events-none disabled:opacity-40 dark:hover:bg-accent/50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0;
}

/* The document toolbar follows the reference's tighter 28px controls. Keep
   this separate from the 32px shell controls so the header does not shrink
   with the post actions. Radius and padding stay opt-in: a split copy group
   needs square inner edges while a standalone share button stays rounded. */
@utility post-action-button {
  @apply inline-flex h-7 min-w-7 items-center justify-center gap-1.5 text-sm text-muted-foreground transition-colors select-none active:scale-[0.98] hover:bg-accent hover:text-foreground disabled:pointer-events-none disabled:opacity-40 dark:hover:bg-accent/50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0;
}

/* ---------------------------------------------------------------------------
   Base
--------------------------------------------------------------------------- */

@layer base {
  *,
  ::after,
  ::before,
  ::backdrop,
  ::file-selector-button {
    @apply border-border outline-ring/50;
  }

  html {
    -webkit-text-size-adjust: 100%;
    scroll-behavior: smooth;
  }

  body {
    @apply bg-background text-foreground antialiased;
    font-synthesis-weight: none;
    text-rendering: optimizeLegibility;
  }

  ::selection {
    @apply bg-selection text-selection-foreground;
  }

  /* Suppress every transition until after first paint so the stored theme
     never animates in from the wrong colour. */
  .preload *,
  .preload *::before,
  .preload *::after {
    transition: none !important;
    animation: none !important;
  }

  ::-webkit-scrollbar {
    width: 5px;
    height: 5px;
  }
  ::-webkit-scrollbar-track {
    background: transparent;
  }
  ::-webkit-scrollbar-thumb {
    background: var(--border);
    border-radius: 5px;
  }
  * {
    scrollbar-width: thin;
    scrollbar-color: var(--border) transparent;
  }

  [id] {
    @apply scroll-mt-18;
  }

  /* The field draws its own clear button, in the site's own glyph. WebKit
     offers a second one, in its own, and two crosses in one input is one
     too many. */
  input[type="search"]::-webkit-search-cancel-button {
    -webkit-appearance: none;
    appearance: none;
  }

  /* One focus ring for the whole site. Every keyboard affordance — header
     buttons, palette rows, inline links, the mosaic — draws the same 2px
     outline at the same offset, so focus never changes shape as it moves.
     Components that need a different shape opt out with their own `outline`,
     not with their own ring colour. */
  :focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }
}

/* ---------------------------------------------------------------------------
   Chrome
--------------------------------------------------------------------------- */

.skip-link {
  position: fixed;
  top: 0.75rem;
  left: 50%;
  z-index: 90;
  translate: -50% -300%;
  padding: 0.5rem 0.875rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--background);
  font-family: var(--font-mono);
  font-size: 0.75rem;
  transition: translate 200ms var(--ease-out-quint);
}
.skip-link:focus-visible {
  translate: -50% 0;
}

/* ---------------------------------------------------------------------------
   Typeset — the two long-form measures. `--typeset-flow` is the vertical
   rhythm between blocks, expressed in the block's own em so it scales with
   the measure rather than the root.
--------------------------------------------------------------------------- */

.typeset {
  --typeset-size: 1rem;
  --typeset-leading: 1.65;
  --typeset-flow: 1.25em;

  font-size: var(--typeset-size);
  line-height: var(--typeset-leading);
  text-wrap: pretty;
}

.typeset > * + * {
  margin-top: var(--typeset-flow);
}

.typeset-description {
  --typeset-size: 15px;
  --typeset-leading: 1.6;
  --typeset-flow: 1em;
}

.typeset-timescale {
  --typeset-size: 0.875rem;
  --typeset-leading: 1.5;
  --typeset-flow: 1em;
}

/* ---------------------------------------------------------------------------
   Entrance. The frame is drawn instantly; only the mosaic and the palette
   fade, and neither loops.
--------------------------------------------------------------------------- */

@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

/* Written out rather than run as `fade-in … reverse`: reversing an animation
   that has already finished does not restart it, it re-reads the same finished
   playhead against the other end of the timeline — so the element snaps to the
   far keyframe instead of travelling to it. An exit needs its own name. */
@keyframes fade-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

/* ---------------------------------------------------------------------------
   Figure 404's cell. A square block, no corner rounding, with intensity
   carried by the neutral foreground at five opacities. It was the unit the
   year grid was built from; ADR-0007 removed the grid and the numeral is the
   only thing that still draws it, so it is named for that now.
--------------------------------------------------------------------------- */

.glyph-cell {
  background: color-mix(
    in oklab,
    var(--muted-foreground) var(--level, 10%),
    transparent
  );
  position: relative;
  /* Sized by whatever grid places it — Figure 404's columns are fractions of
     the frame, so the cell holds no measurement of its own. */
  animation: fade-in 260ms var(--ease-out-quint) both;
  animation-delay: calc(var(--col, 0) * 5ms + 320ms);
}

/* An empty frame rather than a fill: the unlit cells of the numeral. */
.glyph-cell[data-recorded="false"] {
  background: transparent;
  box-shadow: inset 0 0 0 1px
    color-mix(in oklab, var(--muted-foreground) 16%, transparent);
}

/* ---------------------------------------------------------------------------
   A single sweep of light across a line of text, once, on load. The gradient
   is painted into the glyphs themselves and slid from right to left, so the
   highlight travels the line rather than the line changing colour. Spread is
   in `ch` so it scales with the type, and the background is twice the element
   plus two spreads wide so the sweep starts and ends fully off the text.
--------------------------------------------------------------------------- */
@keyframes shimmer-sweep {
  0% {
    background-position: 100% 0;
  }
  100% {
    background-position: 0 0;
  }
}

.shimmer {
  --shimmer-spread: calc(3ch + 40px);
  --shimmer-angle: 20deg;
  background-image: linear-gradient(
    calc(90deg + var(--shimmer-angle)),
    currentColor calc(50% - var(--shimmer-spread)),
    color-mix(in oklch, var(--foreground), currentColor 50%)
      calc(50% - var(--shimmer-spread) * 0.5),
    var(--foreground) 50%,
    color-mix(in oklch, var(--foreground), currentColor 50%)
      calc(50% + var(--shimmer-spread) * 0.5),
    currentColor calc(50% + var(--shimmer-spread))
  );
  background-repeat: no-repeat;
  background-size: calc(200% + var(--shimmer-spread) * 2) 100%;
  background-position: 0 0;
  background-clip: text;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: shimmer-sweep 1.5s linear 1;
}

/* Motion is the whole effect, so with it turned off there is nothing left to
   show — paint the text normally rather than leaving it in a frozen gradient. */
@media (prefers-reduced-motion: reduce) {
  .shimmer {
    background-image: none;
    animation: none;
    -webkit-text-fill-color: currentColor;
  }
}

/* ---------------------------------------------------------------------------
   Name pronunciation. The speaker's two waves pulse while the name is being
   said, offset so they read as leaving the cone rather than blinking together.
   Nothing else moves: the glyph is the state, so it must not also be a toy.
--------------------------------------------------------------------------- */
@keyframes pronounce-wave {
  0%,
  100% {
    opacity: 0.3;
  }
  50% {
    opacity: 1;
  }
}

[data-slot="pronounce"][data-speaking] [data-wave="near"] {
  animation: pronounce-wave 0.9s ease-in-out infinite;
}

[data-slot="pronounce"][data-speaking] [data-wave="far"] {
  animation: pronounce-wave 0.9s ease-in-out 0.15s infinite;
}

@media (prefers-reduced-motion: reduce) {
  [data-slot="pronounce"][data-speaking] [data-wave] {
    animation: none;
  }
}

/* ---------------------------------------------------------------------------
   Figure 404. The numeral is drawn in measured cells at plate scale, so the
   page that has no data says so in the site's own unit for it. Cells size
   themselves off the column rather than off a fixed pixel, so the plate is the
   full width of the frame at every viewport.
--------------------------------------------------------------------------- */
.glyph-grid {
  display: grid;
  grid-template-columns: repeat(var(--cols), minmax(0, 1fr));
  gap: 2px;
  width: 100%;
}

.glyph-grid > * {
  aspect-ratio: 1;
}

/* ---------------------------------------------------------------------------
   Prose (MDX) — long-form runs on the serif; structure stays sans.
--------------------------------------------------------------------------- */

.prose {
  /* Set to the frame rather than to a nominal step: the rail is 734px of text
     and the serif ran ~86 characters across it at 17px, well past the line a
     reader can return from without losing their place. 19px brings it back to
     ~75, which is why the body of a post is the largest type on the site. */
  --typeset-size: 1.1875rem;
  --typeset-leading: 1.7;
  --typeset-flow: 1.15em;
  font-family: var(--font-serif);
  color: var(--foreground);
}
.prose h2,
.prose h3 {
  font-family: var(--font-heading);
  font-weight: 500;
  letter-spacing: -0.01em;
  scroll-margin-top: calc(var(--header-height) + 1rem);
}
.prose h2 {
  font-size: 1.5rem;
  line-height: 1.3;
  margin-top: 2.5em;
}
.prose h3 {
  font-size: 1.25rem;
  line-height: 1.35;
  margin-top: 2em;
}
.prose h2 + *,
.prose h3 + * {
  margin-top: 0.75em;
}
.prose > :first-child {
  margin-top: 0;
}
.prose a {
  color: var(--link);
  text-decoration: underline;
  text-decoration-color: color-mix(in oklab, currentColor 30%, transparent);
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  transition: text-decoration-color 150ms var(--ease-out-quint);
}
.prose a:hover {
  text-decoration-color: currentColor;
}
.prose strong {
  font-weight: 600;
}
.prose ul,
.prose ol {
  padding-left: 1.25rem;
}
.prose ul {
  list-style: disc;
}
.prose ol {
  list-style: decimal;
}
.prose li::marker {
  color: var(--muted-foreground);
}
.prose li + li {
  margin-top: 0.5rem;
}
.prose blockquote {
  padding-left: 1.125rem;
  border-left: 2px solid var(--border);
  color: var(--muted-foreground);
  font-style: italic;
}
.prose hr {
  border: 0;
  border-top: 1px solid var(--line);
}
.prose img {
  border: 1px solid var(--line);
}
.prose :not(pre) > code {
  font-family: var(--font-mono);
  font-size: 0.85em;
  background: var(--muted);
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 0.1em 0.35em;
}
.prose pre {
  font-family: var(--font-mono);
  font-size: 0.8125rem;
  line-height: 1.6;
  background: var(--code);
  color: var(--code-foreground);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 1rem 1.125rem;
  overflow-x: auto;
}
.prose pre code {
  background: none;
  border: 0;
  padding: 0;
}
.prose .anchor {
  position: absolute;
}

/* ---------------------------------------------------------------------------
   Glossary marks. The definition stands beside the term the post first uses
   it on, not in a section at the end — a reader who has to leave the sentence
   to find out what a word means has already lost the sentence.
--------------------------------------------------------------------------- */

.glossary {
  position: relative;
  display: inline-block;
  /* The mark and its panel are one thing; a line break between them would put
     the panel under a word the mark is not next to. */
  white-space: nowrap;
}

.prose .glossary-mark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 0.95em;
  height: 0.95em;
  margin-left: 0.15em;
  vertical-align: 0.12em;
  color: var(--muted-foreground);
  cursor: pointer;
  transition: color 150ms var(--ease-out-quint);
}
.prose .glossary-mark svg {
  width: 100%;
  height: 100%;
}
.prose .glossary-mark:hover,
.prose .glossary-mark[aria-expanded="true"] {
  color: var(--foreground);
}

.glossary-panel {
  position: absolute;
  top: calc(100% + 0.6rem);
  left: 50%;
  z-index: 40;
  translate: -50% 0;
  display: block;
  width: max-content;
  max-width: min(22rem, calc(100vw - 2rem));
  padding: 0.75rem 0.875rem;
  border: 1px solid var(--line);
  border-radius: 0.5rem;
  background: var(--popover);
  color: var(--popover-foreground);
  /* The same lift the Menu popover is given, written out because this one is
     styled in CSS rather than in classes. */
  box-shadow:
    0 10px 15px -3px rgb(0 0 0 / 0.1),
    0 4px 6px -4px rgb(0 0 0 / 0.1);
  font-family: var(--font-sans);
  font-size: 0.875rem;
  line-height: 1.55;
  white-space: normal;
  text-wrap: pretty;
  animation: glossary-in 140ms var(--ease-out-quint) both;
}

.glossary-term {
  display: block;
  margin-bottom: 0.35rem;
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  /* Set in the micro-label's mono, but not uppercased: the term is the
     author's word, and the author writes in lowercase. */
  color: var(--muted-foreground);
}

.glossary-definition {
  display: block;
}

@keyframes glossary-in {
  from {
    opacity: 0;
    transform: translateY(-2px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

/* sugar-high — four roles, no rainbow */
.prose pre .sh__token--keyword,
.prose pre .sh__token--sign {
  color: var(--link);
}
.prose pre .sh__token--string,
.prose pre .sh__token--property {
  color: var(--muted-foreground);
}
.prose pre .sh__token--comment {
  color: var(--code-number);
}
.prose pre .sh__token--identifier,
.prose pre .sh__token--entity {
  color: var(--foreground);
}

/* ---------------------------------------------------------------------------
   Command palette
--------------------------------------------------------------------------- */

@keyframes palette-in {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes palette-out {
  from {
    opacity: 1;
    transform: none;
  }
  to {
    opacity: 0;
    transform: scale(0.95);
  }
}

/* The reference opens its dialog in a tenth of a second, from 95% and
   centred — no rise. A dialog that is already under the cursor's attention
   does not need to travel to earn it.

   It leaves the same way. React unmounts a node the instant its state says so,
   which is why the exit needs `usePresence` to hold the node for the length of
   the animation — CSS alone, `@starting-style` included, never gets a frame. */
.palette-panel {
  animation: palette-in 100ms var(--ease-out-quint) both;
}

.palette-panel[data-state="closed"] {
  animation: palette-out 100ms var(--ease-out-quint) both;
}

.palette-backdrop {
  animation: fade-in 160ms linear both;
  background: color-mix(in oklab, var(--background) 62%, transparent);
  backdrop-filter: blur(6px);
}

/* The backdrop takes longer to arrive than to leave, and leaves in step with
   the panel rather than outliving it: a dismissal that is still fading after
   the thing being dismissed has gone reads as lag. */
.palette-backdrop[data-state="closed"] {
  animation: fade-out 100ms linear both;
}

/* ---------------------------------------------------------------------------
   Project disclosure. A row opens by growing its own track from nothing, so
   the record can be one line or five and the row never has to be measured
   first. `visibility` rather than `display`, so the closed record stays out of
   the tab order and off the screen reader without killing the transition.
--------------------------------------------------------------------------- */
.project-details {
  grid-template-rows: 0fr;
  visibility: hidden;
  transition:
    grid-template-rows 240ms var(--ease-out-quint),
    visibility 240ms;
}

.project-details[data-open="true"] {
  grid-template-rows: 1fr;
  visibility: visible;
}

/* ---------------------------------------------------------------------------
   Reduced motion: movement goes, colour feedback stays.
--------------------------------------------------------------------------- */

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-delay: 0ms !important;
    animation-iteration-count: 1 !important;
    /* Movement goes, colour stays — so this whitelists the properties that
       are not movement rather than saying `transition: none`. A blanket kill
       would take the hover tint with it, and the hover tint is precisely the
       feedback this block exists to preserve (DESIGN.md §5). Everything left
       out — transform, rotate, translate, grid rows, height — snaps. */
    transition-property:
      color, background-color, border-color, outline-color, text-decoration-color,
      fill, stroke, box-shadow, opacity, filter !important;
  }
  .glyph-cell,
  .palette-panel,
  .palette-backdrop {
    animation: none !important;
    opacity: 1;
    transform: none;
  }
}

