input.command:
cat > public/lab/blog-reference.html <<'HTMLEOF'
<!doctype html>
<html lang="en" data-theme="dark" data-face="sans">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>gpt-5.6 review: after burning 3.5b tokens</title>
<meta name="description" content="gpt-5.6 is like a bull that keeps hitting the wall until the wall breaks. the surprising part is how efficient it is while doing that." />
<meta name="color-scheme" content="dark light" />
<meta name="theme-color" content="#0a0a0b" />

<!-- Same families as dhruv2mars.com — Geist, Geist Mono, IBM Plex Serif.
     Only the CSS differs, so this page isolates layout from typeface. -->
<link rel="preconnect" href="https://fonts.googleapis.com" />
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Geist:wght@400..700&family=Geist+Mono:wght@400;500&family=IBM+Plex+Serif:ital,wght@0,400;0,500;0,600;1,400&display=swap" />

<style>
/* ─────────────────────────────────────────────────────────────
   TYPE SPEC — every number measured against five reference posts
   (Vercel · OpenAI · Shumer · Anthropic Eng · Stripe)

   rail 660  ·  body 17/27.2 (1.60)  ·  ¶ gap 23.8 → advance 1.88×
   h1 46 (2.71× body) · h2 27 (1.59×) · h3 20 (1.18×)
   h2 space 48 above / 17.6 below (2.7:1, 1.76 body lines)
   ───────────────────────────────────────────────────────────── */
:root {
  --rail: 660px;
  --gutter: 24px;
  --header-h: 56px;

  --sans:  "Geist", -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, sans-serif;
  --serif: "IBM Plex Serif", "Iowan Old Style", Palatino, ui-serif, Georgia, serif;
  --mono:  "Geist Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;

  --body-size: 1.0625rem;   /* 17px */
  --body-lead: 1.6;         /* 27.2px */
  --body-flow: 1.4em;       /* 23.8px → line-advance ratio 1.88 */

  --step-h1:    2.875rem;   /* 46px */
  --step-h2:    1.6875rem;  /* 27px */
  --step-h3:    1.25rem;    /* 20px */
  --step-lede:  1.3125rem;  /* 21px */
  --step-small: 0.8125rem;  /* 13px */
  --step-micro: 0.75rem;    /* 12px */

  --space-h2: 3rem;         /* 48px above a section heading */
  --space-h3: 2rem;

  --ease: cubic-bezier(.32, .72, 0, 1);
}

/* Serif runs optically smaller at the same px. +1px keeps x-height matched
   so the two faces are compared at equal apparent size, not equal em. */
html[data-face="serif"] { --body-size: 1.125rem; --body-lead: 1.62; }

html[data-theme="dark"] {
  color-scheme: dark;
  --bg:        #0a0a0b;
  --surface:   #131316;
  --fg:        #e4e4e7;   /* not #fff — pure white haloes on near-black */
  --fg-strong: #f4f4f5;
  --muted:     #8f8f99;   /* 6.2:1 on --bg */
  --line:      rgba(255,255,255,.09);
  --line-soft: rgba(255,255,255,.055);
  --accent:    #7dd3fc;
  --mark:      rgba(125,211,252,.15);
  --ring:      #7dd3fc;
}
html[data-theme="light"] {
  color-scheme: light;
  --bg:        #fcfcfb;
  --surface:   #f3f3f1;
  --fg:        #26262a;
  --fg-strong: #0d0d0f;
  --muted:     #6c6c75;   /* 4.9:1 on --bg */
  --line:      rgba(0,0,0,.11);
  --line-soft: rgba(0,0,0,.06);
  --accent:    #0369a1;
  --mark:      rgba(3,105,161,.11);
  --ring:      #0369a1;
}

* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; scroll-behavior: smooth; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font-family: var(--sans);
  font-size: var(--body-size);
  line-height: var(--body-lead);
  font-feature-settings: "kern" 1, "liga" 1;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  transition: background-color .2s var(--ease), color .2s var(--ease);
}
html[data-face="serif"] body { font-family: var(--serif); }

::selection { background: var(--mark); color: var(--fg-strong); }

:where(a, button, summary, [tabindex]):focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 3px;
  border-radius: 3px;
}

.skip {
  position: absolute; left: -9999px; top: 0; z-index: 100;
  padding: 10px 16px;
  background: var(--surface); color: var(--fg-strong);
  border: 1px solid var(--line); border-radius: 8px;
  font: 500 var(--step-small)/1 var(--mono); text-decoration: none;
}
.skip:focus { left: 16px; top: 12px; }

.rail {
  width: 100%;
  max-width: calc(var(--rail) + var(--gutter) * 2);
  margin-inline: auto;
  padding-inline: var(--gutter);
}

/* ── reading progress ─────────────────────────────────────── */
#bar {
  position: fixed; inset: 0 auto auto 0;
  height: 2px; width: 0;
  background: var(--fg-strong); opacity: .45;
  z-index: 60; will-change: width;
}

/* ── header ───────────────────────────────────────────────── */
header.site {
  position: sticky; top: 0; z-index: 50;
  height: var(--header-h);
  display: flex; align-items: center;
  background: color-mix(in srgb, var(--bg) 84%, transparent);
  backdrop-filter: saturate(150%) blur(14px);
  -webkit-backdrop-filter: saturate(150%) blur(14px);
  border-bottom: 1px solid transparent;
  transition: border-color .2s var(--ease);
}
header.site[data-stuck="true"] { border-bottom-color: var(--line); }
header.site .rail { display: flex; align-items: center; justify-content: space-between; gap: 16px; }

/* the wordmark sits on the SAME left edge as the article text. no drift. */
.wordmark {
  font: 500 var(--step-small)/1 var(--mono);
  letter-spacing: -.01em;
  color: var(--fg-strong); text-decoration: none;
}
.wordmark span { color: var(--muted); }

.switches { display: flex; gap: 6px; }
.switches button {
  font: 500 var(--step-micro)/1 var(--mono);
  letter-spacing: .02em;
  color: var(--muted);
  background: transparent;
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 6px 11px;
  cursor: pointer;
  transition: color .15s var(--ease), border-color .15s var(--ease);
}
.switches button:hover { color: var(--fg-strong); border-color: var(--muted); }

/* ── table of contents (fills the gutter that would otherwise be dead) ── */
.toc { display: none; }
@media (min-width: 1280px) {
  .toc {
    display: block;
    position: fixed;
    top: calc(var(--header-h) + 48px);
    left: calc(50% - 558px);
    width: 178px;
    max-height: calc(100vh - var(--header-h) - 96px);
    overflow-y: auto;
    overscroll-behavior: contain;
    z-index: 20;
    opacity: 0;
    transform: translateY(4px);
    transition: opacity .3s var(--ease), transform .3s var(--ease);
    pointer-events: none;
  }
  .toc[data-visible="true"] { opacity: 1; transform: none; pointer-events: auto; }
}
.toc h2 {
  font: 500 var(--step-micro)/1 var(--mono);
  letter-spacing: .07em; text-transform: uppercase;
  color: var(--muted);
  margin: 0 0 14px;
}
.toc ol { list-style: none; margin: 0; padding: 0; }
.toc li + li { margin-top: 2px; }
.toc a {
  display: block;
  padding: 5px 0 5px 12px;
  border-left: 1px solid var(--line);
  font-size: var(--step-small);
  font-family: var(--sans);
  line-height: 1.35;
  color: var(--muted);
  text-decoration: none;
  transition: color .18s var(--ease), border-color .18s var(--ease);
}
.toc a:hover { color: var(--fg); border-left-color: var(--muted); }
.toc a[aria-current="true"] { color: var(--fg-strong); border-left-color: var(--fg-strong); }

/* ── masthead ─────────────────────────────────────────────── */
.masthead { padding-top: 88px; }

.eyebrow {
  display: flex; align-items: center; gap: 10px; flex-wrap: wrap;
  font: 500 var(--step-micro)/1 var(--mono);
  letter-spacing: .05em; text-transform: uppercase;
  color: var(--muted);
  margin: 0 0 24px;
}
.eyebrow .dot { width: 3px; height: 3px; border-radius: 50%; background: currentColor; opacity: .55; }

h1 {
  font-family: var(--sans);
  font-size: var(--step-h1);
  line-height: 1.06;
  letter-spacing: -.028em;
  font-weight: 640;
  color: var(--fg-strong);
  margin: 0;
  text-wrap: balance;
}

.lede {
  font-family: var(--sans);
  font-size: var(--step-lede);
  line-height: 1.5;
  letter-spacing: -.008em;
  color: var(--muted);
  margin: 22px 0 0;
  max-width: 34em;
  text-wrap: pretty;
}
html[data-face="serif"] .lede { font-family: var(--serif); letter-spacing: 0; }

.byline {
  display: flex; align-items: center; gap: 11px;
  margin: 36px 0 0; padding-bottom: 36px;
  font: 400 var(--step-small)/1 var(--mono);
  color: var(--muted);
}
.monogram {
  display: grid; place-items: center;
  width: 28px; height: 28px; border-radius: 50%;
  border: 1px solid var(--line);
  background: var(--surface);
  font: 500 11px/1 var(--mono);
  letter-spacing: .02em;
  color: var(--fg);
  flex: none;
}
.byline b { color: var(--fg); font-weight: 500; }

hr.rule { border: 0; border-top: 1px solid var(--line); margin: 0; }

/* ── prose ────────────────────────────────────────────────── */
.prose { padding-top: 48px; padding-bottom: 8px; }
.prose > * { margin: 0; }
.prose > * + * { margin-top: var(--body-flow); }
.prose p { text-wrap: pretty; }

.prose h2 {
  font-family: var(--sans);
  font-size: var(--step-h2);
  line-height: 1.22;
  letter-spacing: -.018em;
  font-weight: 620;
  color: var(--fg-strong);
  margin-top: var(--space-h2);
  scroll-margin-top: calc(var(--header-h) + 28px);
  text-wrap: balance;
}
.prose h3 {
  font-family: var(--sans);
  font-size: var(--step-h3);
  line-height: 1.3;
  letter-spacing: -.012em;
  font-weight: 600;
  color: var(--fg-strong);
  margin-top: var(--space-h3);
  scroll-margin-top: calc(var(--header-h) + 28px);
}
/* proximity: a heading belongs to what FOLLOWS it, not what precedes it */
.prose h2 + *, .prose h3 + * { margin-top: 1.1rem; }
.prose > :first-child { margin-top: 0; }

.prose a {
  color: var(--fg);
  text-decoration: underline;
  text-decoration-color: color-mix(in srgb, var(--fg) 34%, transparent);
  text-underline-offset: 3px;
  text-decoration-thickness: 1px;
  transition: text-decoration-color .15s var(--ease);
}
.prose a:hover { text-decoration-color: var(--fg); }
.prose strong { color: var(--fg-strong); font-weight: 620; }

code {
  font-family: var(--mono);
  font-size: .86em;
  padding: .16em .42em;
  border-radius: 5px;
  background: var(--surface);
  border: 1px solid var(--line-soft);
  color: var(--fg-strong);
}

.prose ul { padding-left: 0; list-style: none; }
.prose li { position: relative; padding-left: 1.35em; }
.prose li + li { margin-top: .5em; }
.prose li::before {
  content: ""; position: absolute;
  left: .18em; top: calc(var(--body-lead) * .5em - 2.5px);
  width: 5px; height: 5px; border-radius: 50%;
