(function () {
  var html = document.documentElement;
  var KEY = 'blogref.prefs';

  /* ── preferences: stored, else system ─────────────────────── */
  var saved = {};
  try { saved = JSON.parse(localStorage.getItem(KEY)) || {}; } catch (e) {}
