  function save() {
    try { localStorage.setItem(KEY, JSON.stringify({ theme: html.dataset.theme, face: html.dataset.face })); } catch (e) {}
  }
  function sync() {
    var dark = html.dataset.theme === 'dark';
    var sans = html.dataset.face === 'sans';
    bTheme.textContent = dark ? 'light' : 'dark';
    bFace.textContent  = sans ? 'serif' : 'sans';
    bTheme.setAttribute('aria-pressed', String(!dark));
    bFace.setAttribute('aria-pressed', String(!sans));
    bTheme.setAttribute('aria-label', 'switch to ' + (dark ? 'light' : 'dark') + ' theme');
    bFace.setAttribute('aria-label', 'switch body text to ' + (sans ? 'serif' : 'sans-serif'));
    var meta = document.querySelector('meta[name="theme-color"]');
    if (meta) meta.setAttribute('content', dark ? '#0a0a0b' : '#fcfcfb');
  }
  bTheme.addEventListener('click', function () {
    html.dataset.theme = html.dataset.theme === 'dark' ? 'light' : 'dark'; sync(); save();
  });
  bFace.addEventListener('click', function () {
    html.dataset.face = html.dataset.face === 'sans' ? 'serif' : 'sans'; sync(); save();
  });
  sync();

  /* ── progress bar + sticky header shadow ──────────────────── */
  var bar = document.getElementById('bar');
  var hdr = document.getElementById('hdr');
  var toc = document.getElementById('toc');
  var ticking = false;

  function onScroll() {
    if (ticking) return;
    ticking = true;
    requestAnimationFrame(function () {
      var y = window.scrollY;
      var max = document.documentElement.scrollHeight - window.innerHeight;
      bar.style.width = (max > 0 ? Math.min(100, (y / max) * 100) : 0) + '%';
      hdr.dataset.stuck = y > 8 ? 'true' : 'false';
      toc.dataset.visible = y > 220 ? 'true' : 'false';
      ticking = false;
    });
  }
  window.addEventListener('scroll', onScroll, { passive: true });
  window.addEventListener('resize', onScroll, { passive: true });
  onScroll();

  /* ── scroll-spy: mark the section you are actually reading ── */
  var links = [].slice.call(toc.querySelectorAll('a'));
  var targets = links
    .map(function (a) { return document.getElementById(a.getAttribute('href').slice(1)); })
    .filter(Boolean);

  function spy() {
    var line = window.scrollY + window.innerHeight * 0.28;
    var idx = -1;
    for (var i = 0; i < targets.length; i++) {
      if (targets[i].offsetTop <= line) idx = i;
    }
    for (var j = 0; j < links.length; j++) {
      if (j === idx) links[j].setAttribute('aria-current', 'true');
      else links[j].removeAttribute('aria-current');
    }
  }
  var spying = false;
  window.addEventListener('scroll', function () {
    if (spying) return;
    spying = true;
    requestAnimationFrame(function () { spy(); spying = false; });
  }, { passive: true });
  spy();
})();
</script>

