python3 - <<'PY'
import io
p='app/globals.css'
s=io.open(p,encoding='utf-8').read(); o=s
def sub(a,b):
    global s
    assert s.count(a)==1, ('count=%d'%s.count(a))+' :: '+a[:80]
    s=s.replace(a,b)

sub("""  --typeset-size: 1.1875rem;
  --typeset-leading: 1.7;
  --typeset-flow: 1.15em;
  font-family: var(--font-serif);
  color: var(--foreground);
}""",
"""  --typeset-size: 1.1875rem;
  --typeset-leading: 1.7;
  /* A paragraph break has to be worth more than a line break or the eye stops
     seeing where one paragraph ends. At 1.15em the gap was 0.68 of a line and
     the total advance between paragraphs only 1.68x a line — the tightest of
     the six posts this was measured against, all of which sit at 1.81-2.03.
     1.45em puts it at 1.85x. */
  --typeset-flow: 1.45em;
  /* One body line. Every vertical space below is a multiple of this rather
     than an em of the heading it sits on, so changing a heading's size moves
     the heading and not the rhythm around it. */
  --prose-line: calc(var(--typeset-size) * var(--typeset-leading));
  font-family: var(--font-serif);
  color: var(--foreground);
}
/* Body text steps back off pure white; headings keep it. On a near-black
   background a 400-weight serif at full --foreground haloes, and the gap
   between the two gives the page a second hierarchy channel besides size. */
.dark .prose {
  color: oklch(0.91 0.004 286.1);
}
.dark .prose h2,
.dark .prose h3,
.dark .prose strong {
  color: var(--foreground);
}""")

sub(""".prose h2 {
  font-size: 1.5rem;
  line-height: 1.3;
  margin-top: 2.5em;
}
.prose h3 {
  font-size: 1.25rem;
  line-height: 1.35;
  margin-top: 2em;
}
.prose h2 + *,
.prose h3 + * {
  margin-top: 0.75em;
}""",
"""/* The scale was flat — h2 was 1.26x the body, so nothing announced a section
   and the post could not be skimmed. 1.58x is the median of the six reference
   posts. The space above then comes down rather than up: a heading that is
   visibly larger needs less room to separate itself, and space is only there
   to assist. */
.prose h2 {
  font-size: 1.875rem;
  line-height: 1.25;
  margin-top: calc(var(--prose-line) * 1.76);
}
.prose h3 {
  font-size: 1.375rem;
  line-height: 1.3;
  margin-top: calc(var(--prose-line) * 1.17);
}
/* A heading belongs to what follows it, not to what it follows. 2.7:1 is the
   split; below 2:1 the heading starts to look like it caps the section above. */
.prose h2 + *,
.prose h3 + * {
  margin-top: calc(var(--prose-line) * 0.65);
}""")

assert s!=o
io.open(p,'w',encoding='utf-8').write(s)
print('globals.css ok')
